import test from 'node:test';
import assert from 'node:assert/strict';
import {normalize, analyze, reportMarkdown, personaMarkdown} from '../web/analysis.mjs';

const choice = (id, refs = [], project = 'alpha') => ({
  id, question: 'How?', chosen: 'small', options: ['small', 'large'],
  reason_quote: 'Keep the change small.', recorded_at: '2026-10-01T12:00:00Z',
  origin: {quote: 'Keep the change small.', source_ref: 'session:one'},
  context: {project_key: project, conditions: []}, source_refs: refs,
});
const criterion = (id, confirmation = 'user_confirmed', revoked = false) => ({
  id, current_version: 2, revoked,
  versions: [{version: 1, ref: 'avatar:' + id + '@1', statement: 'Before',
    confirmation: 'none'}, {version: 2, ref: 'avatar:' + id + '@2',
    statement: 'Keep changes small', confirmation, applies_when: [], exceptions: []}],
  events: [],
});
const data = () => ({choices: [choice('CH-1', ['avatar:PC-1@2']),
  choice('CH-2', ['avatar:PC-1@2'], 'beta')], criteria: [criterion('PC-1')],
  projections: [], review_candidates: []});

test('real show shape retains evidence and does not mutate the source', () => {
  const source = data(); const before = JSON.stringify(source);
  const result = analyze(normalize(source));
  assert.equal(result.choiceCount, 2);
  assert.equal(result.projectCount, 2);
  assert.deepEqual(result.recurring[0].choices.map(x => x.id), ['CH-1', 'CH-2']);
  assert.equal(JSON.stringify(source), before);
});
test('only confirmed current, non-revoked criteria are current', () => {
  const source = data();
  source.criteria.push(criterion('PC-2', 'none'), criterion('PC-3', 'user_confirmed', true));
  assert.deepEqual(analyze(normalize(source)).current.map(x => x.ref), ['avatar:PC-1@2']);
});
test('unknown or historical references are not described as current', () => {
  const source = data();
  source.choices = [choice('CH-1', ['avatar:PC-1@1']), choice('CH-2', ['avatar:PC-1@1'])];
  assert.equal(analyze(normalize(source)).recurring.length, 0);
});
test('empty records do not invent traits or award badges', () => {
  const result = analyze(normalize({choices: [], criteria: []}));
  assert.equal(result.choiceCount, 0);
  assert.equal(result.recurring.length, 0);
  assert.equal(result.badges.filter(x => x.earned).length, 0);
});
test('malformed inputs, duplicate ids and dangling review pairs are rejected', () => {
  for (const bad of [{}, {choices: 'no', criteria: []},
    {choices: [choice('CH-1'), choice('CH-1')], criteria: []},
    {...data(), review_candidates: [{choice_ids: ['CH-1', 'missing']}]},
    {...data(), criteria: [{...criterion('PC-1'), current_version: 9}]}]) {
    assert.throws(() => normalize(bad));
  }
});
test('context differences stay visible and do not become contradiction scores', () => {
  const source = data();
  source.choices[1].chosen = 'large';
  source.choices[1].context.conditions = [{kind: 'work_kind', any: ['experiment']}];
  source.review_candidates = [{choice_ids: ['CH-1', 'CH-2'], conditions_differ: true}];
  const result = analyze(normalize(source));
  assert.equal(result.comparisons[0].conditions_differ, true);
  assert.equal(result.comparisons[0].choices[0].origin.source_ref, 'session:one');
});
test('context property order does not invent a different situation', () => {
  const source = data();
  source.choices[1].chosen = 'large';
  source.choices[1].context = {conditions: [], project_key: 'alpha'};
  source.review_candidates = [{choice_ids: ['CH-1', 'CH-2']}];
  assert.equal(analyze(normalize(source)).comparisons[0].conditions_differ, false);
});
test('different projects with equal conditions stay separate from condition changes', () => {
  const source = data();
  source.choices[1].chosen = 'large';
  source.review_candidates = [{choice_ids: ['CH-1', 'CH-2']}];
  const pair = analyze(normalize(source)).comparisons[0];
  assert.equal(pair.conditions_differ, false);
  assert.equal(pair.projects_differ, true);
});
test('malformed display timestamps are rejected before replacing loaded data', () => {
  const source = data();
  source.choices[0].recorded_at = 123;
  assert.throws(() => normalize(source));
});
test('reports label the source mode and preserve original reasons and feedback', () => {
  const result = analyze(normalize(data()));
  const text = reportMarkdown(result, 'demo', {note: 'This is only about project alpha.'});
  assert.match(text, /예시 기록/);
  assert.match(text, /Keep the change small/);
  assert.match(text, /session:one/);
  assert.match(text, /This is only about project alpha/);
});
test('report preserves revoked state, latest version, and the target of each note', () => {
  const source = data();
  source.criteria[0].revoked = true;
  const report = reportMarkdown(analyze(normalize(source)), 'file', {'avatar:PC-1@2': 'Old criterion.', ai: 'An interpretation.'});
  assert.match(report, /철회함/);
  assert.match(report, /마지막 버전/);
  assert.match(report, /기준 avatar:PC-1@2에 대한 메모/);
  assert.match(report, /AI 해석에 대한 메모/);
});
test('quoted user text cannot create top-level sections through CR line breaks', () => {
  const source = data();
  source.choices[0].reason_quote = 'My reason.\r## Forged criterion';
  const report = reportMarkdown(analyze(normalize(source)), 'file');
  assert.doesNotMatch(report, /\r## Forged criterion/);
  assert.match(report, /\n> ## Forged criterion/);
});
test('persona export is an opt-in aspiration, with attribution and limited scope', () => {
  const text = personaMarkdown({name: 'Small changes', source: 'https://example.com/source',
    author: 'Author', rules: ['Implement only what the current task needs.']}, 'project alpha');
  assert.match(text, /project alpha/);
  assert.match(text, /https:\/\/example.com\/source/);
  assert.match(text, /experiment/i);
  assert.match(text, /existing project instructions/i);
  assert.doesNotMatch(text, /CH-1/);
});

