import test from 'node:test';
import assert from 'node:assert/strict';
import {analysisPayload, aiSection, aiMarkdown, selectionHtml} from '../web/ai.mjs';
import {demo} from '../web/content.mjs';

test('analysis sends only selected records and their referenced criterion versions', () => {
  const data = structuredClone(demo);
  data.choices[0].source_refs = ['avatar:PC-a00000000001@1'];
  data.choices[0].context.private = 'not for analysis';
  const payload = analysisPayload(data, [data.choices[0].id]);
  assert.equal(payload.choices.length, 1);
  assert.equal(payload.criteria.length, 1);
  assert.equal(payload.criteria[0].current, false);
  assert.equal(payload.criteria[0].confirmation, 'none');
  assert.equal(payload.choices[0].origin, undefined);
  assert.equal(payload.choices[0].context.private, undefined);
  assert.equal(payload.criteria[0].origin, undefined);
  assert.throws(() => analysisPayload(data, []));
  assert.throws(() => analysisPayload(data, ['missing']));
});
test('record picker starts empty and exposes the payload preview', () => {
  const html = selectionHtml(demo, 'demo', true);
  assert.doesNotMatch(html, / checked/);
  assert.match(html, /<details open>/);
  assert.match(html, /id="ai-start"[^>]*disabled/);
});
test('AI text is escaped on screen and export preserves evidence and limitations', () => {
  const analysis = {headline: '<img src=x onerror=alert(1)>', summary: 'Summary',
    insights: [{title: 'Title', interpretation: '<script>alert(1)</script>\n## Forged section\r## CR section',
      alternative: 'Different context', evidence_ids: [demo.choices[0].id]}],
    next_question: 'A question', limitations: ['One record'], analyzed_at: 'today',
    selected_ids: [demo.choices[0].id]};
  const html = aiSection(analysis, false, 1);
  assert.doesNotMatch(html, /<script>|<img/);
  assert.match(html, /&lt;script&gt;/);
  const report = aiMarkdown(analysis);
  assert.match(report, /CH-c00000000001/);
  assert.match(report, /One record/);
  assert.match(report, /확인한 개인 기준이 아닙니다/);
  assert.doesNotMatch(report, /\n## Forged section/);
  assert.match(report, /\n> ## Forged section/);
  assert.doesNotMatch(report, /\r## CR section/);
  assert.match(report, /\n> ## CR section/);
});
